static bool vext_narrow_check_common(DisasContext *s, int vd, int vs2, int vm)
{
    return (s->lmul <= 2) &&
           (s->sew < MO_64) &&
           ((s->sew + 1) <= (s->cfg_ptr->elen >> 4)) &&
           require_align(vs2, s->lmul + 1) &&  /* 2xLMUL — needs lmul+2 for quad */
           require_align(vd, s->lmul) &&
           require_vm(vm, vd);
}

static bool vext_check_sd(DisasContext *s, int vd, int vs, int vm)
{
    bool ret = vext_narrow_check_common(s, vd, vs, vm) &&
               vext_check_input_eew(s, vs, s->sew + 1, -1, 0, vm);
    if (vd != vs) {
        ret &= require_noover(vd, s->lmul, vs, s->lmul + 1);
    }
    return ret;
}

static bool vext_check_input_eew(DisasContext *s, int vs1, uint8_t eew_vs1,
                                 int vs2, uint8_t eew_vs2, int vm)
{
    bool is_valid = true;
    int8_t emul_vs1 = eew_vs1 - s->sew + s->lmul;  /* lmul+1 for 2x, needs lmul+2 for 4x */
    int8_t emul_vs2 = eew_vs2 - s->sew + s->lmul;
    ...
    if ((vs1 != -1 && vs2 != -1) && (eew_vs1 != eew_vs2) &&
        is_overlapped(vs1, 1 << MAX(emul_vs1, 0),
                      vs2, 1 << MAX(emul_vs2, 0))) {
        is_valid = false;
    }

static bool opfv_narrow_check(DisasContext *s, arg_rmr *a)
{
    return require_rvv(s) &&
           vext_check_isa_ill(s) &&
           /* OPFV narrowing instructions ignore vs1 check */
           vext_check_sd(s, a->rd, a->rs2, a->vm);
}

static inline uint32_t vext_get_total_elems(CPURISCVState *env, uint32_t desc,
                                            uint32_t esz)
{
    uint32_t sew = 1 << FIELD_EX64(env->vtype, VTYPE, VSEW);
    int8_t emul = ctz(esz) - ctz(sew)
                  + FIELD_EX64(desc, VDATA, LMUL);
    return (env->cfg.vlenb << MAX(emul, 0)) / esz;
}

